<?php
namespace ZinCelestial\Platform\Workflow\Durable;defined('ABSPATH')||exit;
final class Schema {public const VERSION='1.8.2';public static function install():void{global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$runs=$wpdb->base_prefix.'zcp_workflow_runs';$events=$wpdb->base_prefix.'zcp_workflow_events';$c=$wpdb->get_charset_collate();dbDelta("CREATE TABLE $runs (site_id bigint unsigned NOT NULL,run_id varchar(191) NOT NULL,payload longtext NOT NULL,version bigint unsigned NOT NULL DEFAULT 1,lease_owner varchar(191) NULL,lease_token char(64) NULL,lease_until datetime(6) NULL,created_at datetime(6) NOT NULL,updated_at datetime(6) NOT NULL,PRIMARY KEY (site_id,run_id),KEY lease_scan (site_id,lease_until),KEY updated_scan (site_id,updated_at)) ENGINE=InnoDB $c;");dbDelta("CREATE TABLE $events (site_id bigint unsigned NOT NULL,event_id char(36) NOT NULL,run_id varchar(191) NOT NULL,event varchar(100) NOT NULL,metadata longtext NOT NULL,created_at datetime(6) NOT NULL,PRIMARY KEY (site_id,event_id),KEY run_timeline (site_id,run_id,created_at)) ENGINE=InnoDB $c;");update_site_option('zcp_workflow_schema_version',self::VERSION);}}
